<?php
if (!defined('ABSPATH')) exit;
add_action('init',function(){if(get_option('bhc_catalog_lg_refrigerator_image_batch_v120')||!function_exists('wc_get_product_id_by_sku'))return;require_once ABSPATH.'wp-admin/includes/image.php';$rows=[['sku'=>'LG-LTB852PFBQ','file'=>'bhc-image-references/LG-LTB852PFBQ-generated-4k.png','title'=>'LG LTB852PFBQ 4K transparent product image'],['sku'=>'LG-GR-V479QGKW','file'=>'bhc-image-references/LG-GR-V479QGKW-generated-4k.png','title'=>'LG GR-V479QGKW 4K transparent product image']];$attached=0;$processed=0;foreach($rows as $row){$id=wc_get_product_id_by_sku($row['sku']);$file=ABSPATH.'wp-content/uploads/'.$row['file'];if(!$id||!is_readable($file))continue;$processed++;$aid=get_post_thumbnail_id($id);$current=$aid?get_post_meta($aid,'_wp_attached_file',true):'';if(!$aid||$current!==$row['file']){$aid=wp_insert_attachment(['post_mime_type'=>'image/png','post_title'=>$row['title'],'post_status'=>'inherit','post_parent'=>$id],$file,$id);if($aid&&!is_wp_error($aid)){update_post_meta($aid,'_wp_attached_file',$row['file']);wp_update_attachment_metadata($aid,['width'=>4096,'height'=>4096,'file'=>$row['file'],'sizes'=>[]]);set_post_thumbnail($id,$aid);$attached++;}}update_post_meta($id,'_bhc_image_generation_status','product_specific_generated');update_post_meta($id,'_bhc_image_status','generated_4k_transparent');update_post_meta($id,'_bhc_image_featured_verified','yes');update_post_meta($id,'_bhc_image_reference_url',wp_get_attachment_url($aid));update_post_meta($id,'_bhc_image_reference_evidence','تصویر اختصاصی همین مدل LG با پرامپت محصول‌محور، PNG شفاف و خروجی 4K تولید و به SKU صحیح متصل شد.');update_post_meta($id,'_bhc_image_reference_checked_at','2026-11-19');}update_option('bhc_catalog_lg_refrigerator_image_batch_v120',['processed'=>$processed,'attached'=>$attached,'at'=>current_time('mysql')],false);},120);
